const LOOKUP = new Map(Object.entries(AVAILABLE).map(([c, ids]) => [c, new Set(ids)]));

// Template lists (unit classes, blueprint categories...) are keyed by a slug of the class name.
export function contentSlug(value: string): string {
  return value.toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
}

export function getContentImage(collection: string, id: string | number): string | undefined {
  const key = String(id);
  if (!LOOKUP.get(collection)?.has(key)) return undefined;
  return `${import.meta.env.BASE_URL}images/content/${collection}/${key}.webp`;
}
